import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Sparkles, Wand2, Image, Hash, Target } from 'lucide-react';

const ContentGenerator = ({ setBlogContent, blogContent }) => {
  const [topic, setTopic] = useState('Artificial Intelligence');
  const [platform, setPlatform] = useState('📸 Instagram');
  const [contentFocus, setContentFocus] = useState('Trending');
  const [isGenerating, setIsGenerating] = useState(false);

  const platforms = [
    '📸 Instagram',
    '🐦 Twitter', 
    '💼 LinkedIn',
    '📺 YouTube',
    '👥 Facebook'
  ];

  const focusOptions = ['Trending', 'Educational', 'Opinion', 'News Analysis'];

  const generateContent = async () => {
    setIsGenerating(true);

    // Simulate AI generation
    setTimeout(() => {
      const mockContent = {
        title: `The Future of ${topic}: Revolutionary Insights for 2024`,
        content: `Discover the transformative power of ${topic} in today's digital landscape. This comprehensive guide explores cutting-edge developments, practical applications, and future trends that are reshaping industries worldwide. From breakthrough innovations to real-world implementations, learn how ${topic} is driving unprecedented change and creating new opportunities for businesses and individuals alike.`,
        hashtags: ['#AI', '#Innovation', '#Technology', '#Future', '#Digital', '#Trending', '#2024', '#Tech', '#Business', '#Growth'],
        cta: `Ready to explore the future of ${topic}? Follow for more insights and join the conversation!`,
        keywords: [topic, 'innovation', 'technology', 'future', '2024'],
        engagement_score: 0.87,
        platform: platform
      };

      setBlogContent(mockContent);
      setIsGenerating(false);
    }, 2000);
  };

  return (
    <div className="content-generator">
      <motion.div 
        className="card"
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4 }}
      >
        <div className="section-header">
          <Sparkles className="section-icon" />
          <h2>AI Content Generator</h2>
        </div>

        <div className="form-grid">
          <div className="form-group">
            <label>📝 Topic</label>
            <input
              type="text"
              className="input-field"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              placeholder="Enter your topic..."
            />
          </div>

          <div className="form-group">
            <label>🚀 Target Platform</label>
            <select
              className="select-field"
              value={platform}
              onChange={(e) => setPlatform(e.target.value)}
            >
              {platforms.map(p => (
                <option key={p} value={p}>{p}</option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label>🎯 Content Focus</label>
            <select
              className="select-field"
              value={contentFocus}
              onChange={(e) => setContentFocus(e.target.value)}
            >
              {focusOptions.map(f => (
                <option key={f} value={f}>{f}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="action-buttons">
          <motion.button
            className="button-primary generate-btn"
            onClick={generateContent}
            disabled={isGenerating}
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            {isGenerating ? (
              <>
                <motion.div
                  animate={{ rotate: 360 }}
                  transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                >
                  <Wand2 size={20} />
                </motion.div>
                Generating...
              </>
            ) : (
              <>
                <Sparkles size={20} />
                Generate AI Content
              </>
            )}
          </motion.button>
        </div>

        {blogContent && (
          <motion.div
            className="generated-content"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <div className="content-header">
              <h3>✨ Generated Content</h3>
              <div className="engagement-score">
                <Target size={16} />
                Engagement: {(blogContent.engagement_score * 100).toFixed(0)}%
              </div>
            </div>

            <div className="content-preview">
              <h4 className="content-title">{blogContent.title}</h4>
              <p className="content-body">{blogContent.content}</p>

              <div className="content-meta">
                <div className="hashtags">
                  <Hash size={16} />
                  <span>{blogContent.hashtags.slice(0, 8).join(' ')}</span>
                </div>

                <div className="cta">
                  <strong>Call to Action:</strong> {blogContent.cta}
                </div>
              </div>
            </div>

            <div className="content-actions">
              <button className="button-secondary">
                <Image size={16} />
                Generate Image
              </button>
              <button className="button-secondary">
                <Hash size={16} />
                More Hashtags
              </button>
            </div>
          </motion.div>
        )}
      </motion.div>

      <style jsx>{`
        .content-generator {
          max-width: 800px;
          margin: 0 auto;
        }

        .section-header {
          display: flex;
          align-items: center;
          gap: 0.75rem;
          margin-bottom: 2rem;
        }

        .section-icon {
          color: #667eea;
        }

        .section-header h2 {
          font-size: 1.75rem;
          font-weight: 600;
          color: #1f2937;
        }

        .form-grid {
          display: grid;
          gap: 1.5rem;
          margin-bottom: 2rem;
        }

        .form-group {
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
        }

        .form-group label {
          font-weight: 500;
          color: #374151;
        }

        .action-buttons {
          display: flex;
          justify-content: center;
          margin-bottom: 2rem;
        }

        .generate-btn {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 1.1rem;
          padding: 1rem 2rem;
        }

        .generated-content {
          border-top: 2px solid #e5e7eb;
          padding-top: 2rem;
        }

        .content-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 1.5rem;
        }

        .content-header h3 {
          color: #1f2937;
          font-size: 1.25rem;
        }

        .engagement-score {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          background: linear-gradient(135deg, #10b981 0%, #059669 100%);
          color: white;
          padding: 0.5rem 1rem;
          border-radius: 20px;
          font-size: 0.9rem;
          font-weight: 500;
        }

        .content-preview {
          background: #f9fafb;
          border-radius: 12px;
          padding: 1.5rem;
          margin-bottom: 1.5rem;
        }

        .content-title {
          color: #1f2937;
          font-size: 1.2rem;
          font-weight: 600;
          margin-bottom: 1rem;
        }

        .content-body {
          color: #4b5563;
          line-height: 1.6;
          margin-bottom: 1.5rem;
        }

        .content-meta {
          display: flex;
          flex-direction: column;
          gap: 1rem;
        }

        .hashtags {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          color: #667eea;
          font-weight: 500;
        }

        .cta {
          color: #374151;
          font-style: italic;
        }

        .content-actions {
          display: flex;
          gap: 1rem;
          justify-content: center;
        }

        .content-actions button {
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }

        @media (max-width: 768px) {
          .content-header {
            flex-direction: column;
            gap: 1rem;
            align-items: flex-start;
          }

          .content-actions {
            flex-direction: column;
          }
        }
      `}</style>
    </div>
  );
};

export default ContentGenerator;
